import React, { useState, useEffect, useRef, useCallback } from "react";

/* =========================================================================
   EYA HAMDI OS — a Windows XP–style desktop environment
   Portfolio simulator for a Healthcare / Medical-AI engineer.
   Pure React + inline styles (skeuomorphic, XP-era chrome). No Tailwind
   trends used for the "OS chrome" on purpose — flat, square, bevelled.
   ========================================================================= */

// ---------- shared skeuomorphic style helpers ----------
const bevelRaised = {
  borderTop: "1px solid #fff",
  borderLeft: "1px solid #fff",
  borderRight: "1px solid #000",
  borderBottom: "1px solid #000",
  boxShadow:
    "inset 1px 1px 0px #dfdfdf, inset -1px -1px 0px #808080",
};
const bevelSunken = {
  borderTop: "1px solid #000",
  borderLeft: "1px solid #000",
  borderRight: "1px solid #fff",
  borderBottom: "1px solid #fff",
  boxShadow: "inset 1px 1px 0px #808080, inset -1px -1px 0px #dfdfdf",
};
const XP_FONT = "'Tahoma','Segoe UI',Arial,sans-serif";
const BLISS_BG = "data:image/jpeg;base64,";
const XP_LOGO_IMG = "data:image/png;base64,";

// ---------- tiny pixel icon renderer (crisp SVG, no anti-alias tricks) ----
function PixelIcon({ kind, size = 32 }) {
  const s = size;
  const common = { width: s, height: s, shapeRendering: "crispEdges" };
  switch (kind) {
    case "computer":
      return (
        <svg {...common} viewBox="0 0 32 32">
          <rect x="4" y="4" width="24" height="16" fill="#c8d3e0" stroke="#33475b" />
          <rect x="7" y="7" width="18" height="10" fill="#1c3f6e" />
          <rect x="10" y="21" width="12" height="3" fill="#8a8f99" />
          <rect x="8" y="24" width="16" height="3" fill="#c8d3e0" stroke="#33475b" />
        </svg>
      );
    case "folder":
      return (
        <svg {...common} viewBox="0 0 32 32">
          <rect x="3" y="9" width="26" height="17" fill="#ffce6b" stroke="#8a5a00" />
          <rect x="3" y="6" width="12" height="5" fill="#ffce6b" stroke="#8a5a00" />
        </svg>
      );
    case "case":
      return (
        <svg {...common} viewBox="0 0 32 32">
          <rect x="4" y="6" width="24" height="20" fill="#e5e9ee" stroke="#33475b" />
          <rect x="4" y="6" width="24" height="5" fill="#8a1f2b" />
          <rect x="8" y="14" width="16" height="2" fill="#8a1f2b" />
          <rect x="8" y="18" width="16" height="2" fill="#33475b" />
          <rect x="8" y="22" width="10" height="2" fill="#33475b" />
        </svg>
      );
    case "terminal":
      return (
        <svg {...common} viewBox="0 0 32 32">
          <rect x="3" y="4" width="26" height="24" fill="#0b0b0b" stroke="#3ddc3d" />
          <rect x="6" y="9" width="6" height="2" fill="#3ddc3d" />
          <rect x="6" y="13" width="14" height="2" fill="#3ddc3d" />
        </svg>
      );
    case "vitals":
      return (
        <svg {...common} viewBox="0 0 32 32">
          <rect x="3" y="4" width="26" height="24" fill="#03231f" stroke="#00ffb0" />
          <polyline points="5,18 10,18 12,10 15,24 18,14 20,18 27,18" fill="none" stroke="#00ffb0" strokeWidth="1.5" />
        </svg>
      );
    case "ie":
      return (
        <svg {...common} viewBox="0 0 32 32">
          <circle cx="16" cy="16" r="12" fill="#2255c4" stroke="#12305e" />
          <path d="M6 16 A10 10 0 0 1 26 16" fill="none" stroke="#f2b100" strokeWidth="2" />
        </svg>
      );
    default:
      return <div style={{ width: s, height: s, background: "#999" }} />;
  }
}

// ---------- ECG pulse svg for tray ----------
function EcgPulse() {
  return (
    <svg width="46" height="16" viewBox="0 0 46 16">
      <polyline
        points="0,8 8,8 11,2 14,14 17,8 46,8"
        fill="none"
        stroke="#39ff14"
        strokeWidth="1.3"
      >
        <animate
          attributeName="points"
          dur="1.4s"
          repeatCount="indefinite"
          values="
            0,8 8,8 11,2 14,14 17,8 46,8;
            -20,8 -12,8 -9,2 -6,14 -3,8 26,8;
            0,8 8,8 11,2 14,14 17,8 46,8"
        />
      </polyline>
    </svg>
  );
}

// =====================================================================
// LOGIN SCREEN (account picker: Visitor / Admin) — reused at boot and Log Off
// =====================================================================
function LoginScreen({ onLogin }) {
  const [passwordFor, setPasswordFor] = useState(null);
  const [password, setPassword] = useState("");
  const [error, setError] = useState(false);
  const [checking, setChecking] = useState(false);

  // The real password never lives in this file — it's checked server-side
  // by /api/login (see api/_auth.js), which hands back a signed token that
  // subsequent write requests must present. If there's no backend deployed
  // yet (e.g. plain `npm run dev`), this will always fail closed.
  const submitAdmin = async () => {
    setChecking(true);
    try {
      const res = await fetch("/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.token) {
        window.__setAdminToken?.(data.token);
        onLogin("admin");
        return;
      }
    } catch (e) {
      // network error, no backend, etc. — fall through to error state
    } finally {
      setChecking(false);
    }
    setError(true);
    setPassword("");
  };

  return (
    <div style={{ height: "100%", width: "100%", display: "flex", flexDirection: "column", fontFamily: XP_FONT }}>
      <div style={{ height: 58, background: "linear-gradient(180deg,#1741c9,#274bd6)", borderBottom: "1px solid #0a2896" }} />
      <div style={{
        flex: 1, position: "relative", overflow: "hidden",
        background: "linear-gradient(135deg,#3f6fe0 0%,#2f57d0 45%,#1c3aad 100%)",
        display: "flex",
      }}>
        <div style={{
          position: "absolute", top: -120, left: -140, width: 480, height: 480, borderRadius: "50%",
          background: "radial-gradient(circle,rgba(255,255,255,0.55),rgba(255,255,255,0) 70%)",
        }} />
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 10 }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
            <span style={{ color: "#fff", fontSize: 30, fontWeight: 400 }}>Windows</span>
            <span style={{ color: "#ffb02e", fontSize: 22, fontStyle: "italic", fontWeight: "bold" }}>eya</span>
          </div>
          <div style={{ color: "#dbe6ff", fontSize: 13, textAlign: "center", maxWidth: 260 }}>
            To begin, click your user name
          </div>
        </div>
        <div style={{ width: 1, background: "rgba(255,255,255,0.5)", margin: "40px 0" }} />
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 22 }}>
          <div
            onClick={() => { window.__clearAdminToken?.(); onLogin("visitor"); }}
            style={{ display: "flex", alignItems: "center", gap: 14, cursor: "pointer", padding: 10, borderRadius: 4, width: 200 }}
            onMouseEnter={(e) => (e.currentTarget.style.background = "rgba(255,255,255,0.12)")}
            onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
          >
            <div style={{
              width: 46, height: 46, background: "#dfe8ff", border: "2px solid #fff",
              display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "1px 1px 4px rgba(0,0,0,0.4)",
            }}>
              <svg width="28" height="28" viewBox="0 0 24 24">
                <circle cx="12" cy="8" r="4.2" fill="#2f57d0" />
                <path d="M4 20c0-4.4 3.6-7 8-7s8 2.6 8 7" fill="#2f57d0" />
              </svg>
            </div>
            <span style={{ color: "#fff", fontSize: 17 }}>Visitor</span>
          </div>

          <div style={{ width: 220 }}>
            <div
              onClick={() => { setPasswordFor(passwordFor === "admin" ? null : "admin"); setError(false); }}
              style={{ display: "flex", alignItems: "center", gap: 14, cursor: "pointer", padding: 10, borderRadius: 4 }}
              onMouseEnter={(e) => (e.currentTarget.style.background = "rgba(255,255,255,0.12)")}
              onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
            >
              <div style={{
                width: 46, height: 46, background: "#ffe3c2", border: "2px solid #fff",
                display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "1px 1px 4px rgba(0,0,0,0.4)",
              }}>
                <svg width="26" height="26" viewBox="0 0 24 24">
                  <rect x="6" y="10" width="12" height="9" rx="1" fill="#a05a1e" />
                  <path d="M8 10V7a4 4 0 018 0v3" fill="none" stroke="#a05a1e" strokeWidth="2" />
                </svg>
              </div>
              <span style={{ color: "#fff", fontSize: 17 }}>Admin</span>
            </div>
            {passwordFor === "admin" && (
              <div style={{ display: "flex", gap: 6, marginTop: 4, marginLeft: 4, alignItems: "center" }}>
                <input
                  type="password"
                  autoFocus
                  value={password}
                  disabled={checking}
                  onChange={(e) => { setPassword(e.target.value); setError(false); }}
                  onKeyDown={(e) => e.key === "Enter" && submitAdmin()}
                  style={{ width: 130, fontSize: 12, padding: "3px 5px", ...bevelSunken, border: "none" }}
                  placeholder="Password"
                />
                <button
                  onClick={submitAdmin}
                  disabled={checking}
                  style={{ ...bevelRaised, background: "#4a7fe0", color: "#fff", fontSize: 12, width: 22, height: 22, cursor: checking ? "default" : "pointer" }}
                >
                  {checking ? "…" : "\u2192"}
                </button>
              </div>
            )}
            {error && (
              <div style={{ color: "#ffd4d4", fontSize: 11, marginTop: 4, marginLeft: 4 }}>
                The password is incorrect. Please try again.
              </div>
            )}
          </div>
        </div>
      </div>
      <div style={{
        height: 46, background: "linear-gradient(180deg,#1c3aad,#122a8c)", borderTop: "1px solid #0a2070",
        display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 16px",
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, color: "#fff", fontSize: 12 }}>
          <div style={{ width: 20, height: 20, borderRadius: "50%", background: "#e2542c", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <div style={{ width: 10, height: 10, borderRadius: "50%", border: "2px solid #fff", borderTop: "2px solid transparent" }} />
          </div>
          Turn off computer
        </div>
        <div style={{ color: "#c7d4f7", fontSize: 10, textAlign: "right" }}>
          After you log on, you can add or change accounts.<br />Just go to Control Panel and click User Accounts.
        </div>
      </div>
    </div>
  );
}

// =====================================================================
// BOOT SEQUENCE
// =====================================================================
function BootSequence({ onDone }) {
  // bios -> xp -> login (waits for click) -> welcome (brief) -> done
  const [stage, setStage] = useState("bios");
  useEffect(() => {
    const t1 = setTimeout(() => setStage("xp"), 1600);
    const t2 = setTimeout(() => setStage("login"), 3400);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  const [loggedRole, setLoggedRole] = useState("visitor");
  const handleLogin = (role) => {
    setLoggedRole(role);
    setStage("welcome");
    setTimeout(() => onDone(role), 900);
  };

  if (stage === "bios") {
    return (
      <div style={{ background: "#000", color: "#e0e0e0", fontFamily: "'Courier New', monospace", fontSize: 13, padding: 20, height: "100vh", width: "100vw" }}>
        <pre style={{ margin: 0, whiteSpace: "pre-wrap" }}>
{`EYA_HAMDI_OS v1.0.4 -- BIOS
Copyright (C) Clinical Systems Research
CPU: Neural-Diagnostic Core @ 3.4GHz
Checking RAM............ 65536MB OK
Detecting Boot Device.... OK
Initializing Medical Subsystems.......
  - X-Ray Classifier Module ......... OK
  - Vitals Monitor Driver ........... OK
  - Research Index .................. OK
Press DEL to enter SETUP (disabled in this build)
Booting EYA_HAMDI_OS...`}
        </pre>
      </div>
    );
  }

  if (stage === "xp") {
    return (
      <div style={{ background: "#000", height: "100vh", width: "100vw", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
        <img src={XP_LOGO_IMG} alt="" style={{ width: 260, imageRendering: "pixelated" }} />
        <div style={{ width: 140, height: 10, border: "1px solid #2b3a6b", overflow: "hidden", position: "relative", background: "#050912", marginTop: 6 }}>
          <div className="xp-loadbar" style={{ position: "absolute", top: 1, bottom: 1, width: 44, display: "flex", gap: 2 }}>
            <div style={{ width: 12, background: "#2f5fd6" }} />
            <div style={{ width: 12, background: "#5b85e8" }} />
            <div style={{ width: 12, background: "#2f5fd6" }} />
          </div>
        </div>
        <style>{`
          @keyframes xp-slide { 0%{left:-50px} 100%{left:140px} }
          .xp-loadbar { animation: xp-slide 1.1s linear infinite; }
        `}</style>
      </div>
    );
  }

  if (stage === "login") {
    return (
      <div style={{ height: "100vh", width: "100vw" }}>
        <LoginScreen onLogin={handleLogin} />
      </div>
    );
  }

  // welcome (brief transitional flash before the desktop reveals)
  return (
    <div style={{ background: "linear-gradient(#0a3fae,#0b1f6e)", height: "100vh", width: "100vw", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 24 }}>
        <div style={{ color: "#fff", fontFamily: XP_FONT, fontSize: 44, fontWeight: 300 }}>
          Welcome{loggedRole === "admin" ? ", Eya" : ""}
        </div>
        <div style={{ width: 2, height: 60, background: "#8fb0f0" }} />
      </div>
    </div>
  );
}

// =====================================================================
// WINDOW FRAME (draggable, focusable, skeuomorphic chrome)
// =====================================================================
function WindowFrame({ win, isActive, onFocus, onClose, onMinimize, onDrag, children }) {
  const dragRef = useRef(null);

  const startDrag = (e) => {
    onFocus(win.id);
    dragRef.current = { startX: e.clientX, startY: e.clientY, ox: win.x, oy: win.y };
    const move = (ev) => {
      if (!dragRef.current) return;
      const dx = ev.clientX - dragRef.current.startX;
      const dy = ev.clientY - dragRef.current.startY;
      onDrag(win.id, dragRef.current.ox + dx, Math.max(0, dragRef.current.oy + dy));
    };
    const up = () => {
      dragRef.current = null;
      window.removeEventListener("mousemove", move);
      window.removeEventListener("mouseup", up);
    };
    window.addEventListener("mousemove", move);
    window.addEventListener("mouseup", up);
  };

  if (win.minimized) return null;

  return (
    <div
      onMouseDown={() => onFocus(win.id)}
      style={{
        position: "absolute",
        left: win.x,
        top: win.y,
        width: win.w,
        height: win.h,
        zIndex: win.z,
        background: "#ece9d8",
        ...bevelRaised,
        border: "2px solid #0a246a",
        display: "flex",
        flexDirection: "column",
        fontFamily: XP_FONT,
      }}
    >
      {/* Title bar */}
      <div
        onMouseDown={startDrag}
        style={{
          height: 26,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "0 3px 0 6px",
          background: isActive
            ? "linear-gradient(180deg,#0A246A 0%,#3169C6 40%,#A6CAF0 100%)"
            : "linear-gradient(180deg,#7b7b7b 0%,#a7a7a7 100%)",
          color: "#fff",
          fontSize: 12,
          fontWeight: "bold",
          cursor: "default",
          userSelect: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
          <PixelIcon kind={win.icon} size={14} />
          <span>{win.title}</span>
        </div>
        <div style={{ display: "flex", gap: 2 }}>
          <button onClick={() => onMinimize(win.id)} style={titleBtnStyle}>_</button>
          <button style={titleBtnStyle}>▢</button>
          <button onClick={() => onClose(win.id)} style={{ ...titleBtnStyle, background: "#c94c3f" }}>✕</button>
        </div>
      </div>
      {/* body */}
      <div style={{ flex: 1, overflow: "auto", background: "#fff", ...bevelSunken, margin: 2 }}>
        {children}
      </div>
    </div>
  );
}
const titleBtnStyle = {
  width: 18,
  height: 17,
  background: "#c9d6f0",
  color: "#000",
  fontSize: 10,
  lineHeight: "17px",
  ...bevelRaised,
  cursor: "pointer",
  padding: 0,
};

// =====================================================================
// APP CONTENT: My Computer
// =====================================================================
const inputStyle = { display: "block", width: "100%", boxSizing: "border-box", fontSize: 12, padding: "3px 5px", marginBottom: 4, ...bevelSunken, border: "none" };

// ---------- generic right-click context menu (used by My Computer) ----------
function ContextMenu({ x, y, items, onClose }) {
  useEffect(() => {
    const handler = () => onClose();
    window.addEventListener("click", handler);
    window.addEventListener("contextmenu", handler);
    window.addEventListener("blur", handler);
    return () => {
      window.removeEventListener("click", handler);
      window.removeEventListener("contextmenu", handler);
      window.removeEventListener("blur", handler);
    };
  }, [onClose]);

  return (
    <div
      onClick={(e) => e.stopPropagation()}
      onContextMenu={(e) => e.preventDefault()}
      style={{
        position: "fixed", left: x, top: y, zIndex: 4000,
        background: "#ece9d8", ...bevelRaised, border: "1px solid #6b6b6b",
        minWidth: 160, fontFamily: XP_FONT, fontSize: 12, padding: 2,
      }}
    >
      {items.map((it, i) =>
        it.divider ? (
          <div key={i} style={{ borderTop: "1px solid #b8b8b8", margin: "2px 0" }} />
        ) : (
          <div
            key={i}
            onClick={() => { it.onClick(); onClose(); }}
            style={{ padding: "4px 10px", cursor: "pointer", color: it.danger ? "#8a1f2b" : "#000" }}
            onMouseEnter={(e) => { e.currentTarget.style.background = "#316ac5"; e.currentTarget.style.color = "#fff"; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; e.currentTarget.style.color = it.danger ? "#8a1f2b" : "#000"; }}
          >
            {it.label}
          </div>
        )
      )}
    </div>
  );
}

const MAX_UPLOAD_BYTES = 4 * 1024 * 1024; // ~4MB — see README for why (built-in storage limits)

function MyComputerApp({ folders, role, onAddFolder, onRenameFolder, onDeleteFolder, onUploadFile, onUpdateFile, onDeleteFile, onLaunchBrowser }) {
  const [openId, setOpenId] = useState(null);
  const [renamingId, setRenamingId] = useState(null);
  const [renameValue, setRenameValue] = useState("");
  const [ctxMenu, setCtxMenu] = useState(null);
  const [linkForm, setLinkForm] = useState(null);
  const fileInputRef = useRef(null);
  const isAdmin = role === "admin";

  const openFolder = folders.find((f) => f.id === openId) || null;

  const showMenu = (e, items) => {
    if (!isAdmin) return;
    e.preventDefault();
    e.stopPropagation();
    setCtxMenu({ x: e.clientX, y: e.clientY, items });
  };

  const startRename = (folder) => { setRenamingId(folder.id); setRenameValue(folder.name); };
  const commitRename = () => {
    if (renameValue.trim()) onRenameFolder(renamingId, renameValue.trim());
    setRenamingId(null);
  };

  const handleNewFolder = () => {
    const name = window.prompt("Folder name:", "New Folder");
    if (name && name.trim()) onAddFolder(name.trim());
  };

  const handleDeleteFolder = (folder) => {
    if (window.confirm(`Delete "${folder.name}" and everything in it? This can't be undone.`)) {
      onDeleteFolder(folder.id);
      if (openId === folder.id) setOpenId(null);
    }
  };

  const triggerUpload = () => fileInputRef.current?.click();

  const handleFileChosen = (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file || !openFolder) return;
    if (file.size > MAX_UPLOAD_BYTES) {
      window.alert(
        `"${file.name}" is ${(file.size / 1024 / 1024).toFixed(1)}MB — that's too large for this demo's built-in storage (~4MB limit per file). Use "Add Link" instead and paste a link to it (e.g. a Google Drive or GitHub link).`
      );
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      onUploadFile(openFolder.id, {
        id: `file-${Date.now()}`,
        name: file.name,
        description: `${(file.size / 1024).toFixed(1)} KB`,
        url: reader.result,
        mimeType: file.type || "",
      });
    };
    reader.readAsDataURL(file);
  };

  const openItem = (item) => {
    if (!item.url) return;
    const previewable = item.mimeType?.startsWith("image/") || item.mimeType === "application/pdf" || /^https?:\/\//.test(item.url);
    if (previewable) {
      onLaunchBrowser(item.url, item.name);
    } else if (item.url.startsWith("data:")) {
      const a = document.createElement("a");
      a.href = item.url;
      a.download = item.name;
      document.body.appendChild(a);
      a.click();
      a.remove();
    } else {
      onLaunchBrowser(item.url, item.name);
    }
  };

  const startEditLink = (item) => setLinkForm({ editingId: item.id, name: item.name, description: item.description, url: item.url || "" });
  const startAddLink = () => setLinkForm({ editingId: null, name: "", description: "", url: "" });
  const saveLink = () => {
    if (!linkForm.name.trim() || !openFolder) return;
    if (linkForm.editingId) {
      onUpdateFile(openFolder.id, linkForm.editingId, { name: linkForm.name, description: linkForm.description, url: linkForm.url });
    } else {
      onUploadFile(openFolder.id, { id: `file-${Date.now()}`, name: linkForm.name, description: linkForm.description, url: linkForm.url, mimeType: "" });
    }
    setLinkForm(null);
  };

  // ---------- ROOT: list of folders ----------
  if (!openFolder) {
    return (
      <div
        style={{ fontFamily: XP_FONT, fontSize: 12, padding: 10, height: "100%", boxSizing: "border-box" }}
        onContextMenu={(e) => showMenu(e, [{ label: "New Folder", onClick: handleNewFolder }])}
      >
        <div style={{ display: "flex", gap: 26, flexWrap: "wrap" }}>
          {folders.map((f) => (
            <div
              key={f.id}
              onDoubleClick={() => setOpenId(f.id)}
              onContextMenu={(e) =>
                showMenu(e, [
                  { label: "Open", onClick: () => setOpenId(f.id) },
                  { label: "Rename", onClick: () => startRename(f) },
                  { divider: true },
                  { label: "Delete", danger: true, onClick: () => handleDeleteFolder(f) },
                ])
              }
              style={{ width: 90, textAlign: "center", cursor: "pointer" }}
            >
              <div style={{ display: "flex", justifyContent: "center" }}><PixelIcon kind="folder" size={38} /></div>
              {renamingId === f.id ? (
                <input
                  autoFocus
                  value={renameValue}
                  onChange={(e) => setRenameValue(e.target.value)}
                  onClick={(e) => e.stopPropagation()}
                  onDoubleClick={(e) => e.stopPropagation()}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") commitRename();
                    if (e.key === "Escape") setRenamingId(null);
                  }}
                  onBlur={commitRename}
                  style={{ width: "100%", fontSize: 12, textAlign: "center", marginTop: 4, ...bevelSunken, border: "none" }}
                />
              ) : (
                <div style={{ marginTop: 4 }}>{f.name}</div>
              )}
            </div>
          ))}
          {folders.length === 0 && <div style={{ color: "#888", fontStyle: "italic" }}>Empty.</div>}
        </div>
        {isAdmin && (
          <div style={{ marginTop: 16, fontSize: 10, color: "#888" }}>
            Right-click for options — New Folder, Rename, Delete.
          </div>
        )}
        {ctxMenu && <ContextMenu {...ctxMenu} onClose={() => setCtxMenu(null)} />}
      </div>
    );
  }

  // ---------- INSIDE A FOLDER ----------
  const items = openFolder.items;
  return (
    <div style={{ fontFamily: XP_FONT, fontSize: 12, padding: 10, height: "100%", boxSizing: "border-box" }}>
      <div style={{ marginBottom: 8, display: "flex", gap: 6, alignItems: "center" }}>
        <button onClick={() => setOpenId(null)} style={{ ...bevelRaised, background: "#ece9d8", fontSize: 11, padding: "1px 8px" }}>◀ Back</button>
        <span>C:\ {openFolder.name}</span>
        {isAdmin && (
          <div style={{ marginLeft: "auto", display: "flex", gap: 6 }}>
            <button onClick={triggerUpload} style={{ ...bevelRaised, background: "#ece9d8", fontSize: 11, padding: "1px 8px" }}>+ Upload File</button>
            <button onClick={startAddLink} style={{ ...bevelRaised, background: "#ece9d8", fontSize: 11, padding: "1px 8px" }}>+ Add Link</button>
          </div>
        )}
      </div>

      <input type="file" ref={fileInputRef} onChange={handleFileChosen} style={{ display: "none" }} />

      {linkForm && (
        <div style={{ ...bevelSunken, background: "#f4f4f4", padding: 8, marginBottom: 8 }}>
          <div style={{ fontWeight: "bold", marginBottom: 4 }}>{linkForm.editingId ? "Edit link" : "Add link"}</div>
          <input placeholder="Name (e.g. cv.pdf)" value={linkForm.name} onChange={(e) => setLinkForm({ ...linkForm, name: e.target.value })} style={inputStyle} />
          <input placeholder="Description" value={linkForm.description} onChange={(e) => setLinkForm({ ...linkForm, description: e.target.value })} style={inputStyle} />
          <input placeholder="URL" value={linkForm.url} onChange={(e) => setLinkForm({ ...linkForm, url: e.target.value })} style={inputStyle} />
          <div style={{ display: "flex", gap: 6, marginTop: 4 }}>
            <button onClick={saveLink} style={{ ...bevelRaised, background: "#ece9d8", fontSize: 11, padding: "1px 8px" }}>Save</button>
            <button onClick={() => setLinkForm(null)} style={{ ...bevelRaised, background: "#ece9d8", fontSize: 11, padding: "1px 8px" }}>Cancel</button>
          </div>
        </div>
      )}

      <div
        onContextMenu={(e) =>
          showMenu(e, [
            { label: "Upload File...", onClick: triggerUpload },
            { label: "Add Link...", onClick: startAddLink },
          ])
        }
        style={{ minHeight: 120 }}
      >
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
          <thead>
            <tr style={{ background: "#0a246a", color: "#fff" }}>
              <th style={{ textAlign: "left", padding: 3 }}>Name</th>
              <th style={{ textAlign: "left", padding: 3 }}>Description</th>
              {isAdmin && <th style={{ padding: 3 }} />}
            </tr>
          </thead>
          <tbody>
            {items.map((file, i) => (
              <tr key={file.id} style={{ background: i % 2 ? "#eef2fb" : "#fff" }}>
                <td
                  style={{ padding: 3, cursor: file.url ? "pointer" : "default", color: file.url ? "#0a246a" : "#000", textDecoration: file.url ? "underline" : "none" }}
                  onDoubleClick={() => openItem(file)}
                  title={file.url ? "Double-click to open" : ""}
                >
                  {file.name}
                </td>
                <td style={{ padding: 3, color: "#555" }}>{file.description}</td>
                {isAdmin && (
                  <td style={{ padding: 3, whiteSpace: "nowrap" }}>
                    <button onClick={() => startEditLink(file)} style={{ ...bevelRaised, fontSize: 10, padding: "0 5px", marginRight: 3 }}>Edit</button>
                    <button onClick={() => onDeleteFile(openFolder.id, file.id)} style={{ ...bevelRaised, fontSize: 10, padding: "0 5px" }}>✕</button>
                  </td>
                )}
              </tr>
            ))}
            {items.length === 0 && (
              <tr><td colSpan={isAdmin ? 3 : 2} style={{ padding: 6, color: "#888", fontStyle: "italic" }}>Empty folder.{isAdmin ? " Right-click, or use the buttons above, to add a file." : ""}</td></tr>
            )}
          </tbody>
        </table>
      </div>
      {items.some((f) => f.url) && <div style={{ marginTop: 6, fontSize: 10, color: "#777" }}>Double-click a linked file name to open or download it.</div>}
      {ctxMenu && <ContextMenu {...ctxMenu} onClose={() => setCtxMenu(null)} />}
    </div>
  );
}

