function normalizeDocs(raw) {
  if (Array.isArray(raw)) return raw;
  if (raw && typeof raw === "object") {
    return Object.entries(raw).map(([name, items], i) => ({
      id: `folder-legacy-${i}`,
      name,
      items: Array.isArray(items) ? items : [],
    }));
  }
  return DEFAULT_DOCS;
}

