function TerminalApp({ cases, role }) {
  const [lines, setLines] = useState([
    "EYA_HAMDI_OS Terminal [Version 1.0.4]",
    "Type 'help' for a list of commands.",
    "",
  ]);
  const [input, setInput] = useState("");
  const bottomRef = useRef(null);

  useEffect(() => { bottomRef.current?.scrollIntoView(); }, [lines]);

  const run = (cmdRaw) => {
    const cmd = cmdRaw.trim();
    const out = [`C:\\EYA_HAMDI> ${cmd}`];
    switch (cmd.toLowerCase()) {
      case "help":
        out.push("Commands: help, whoami, ls, cat resume.txt, projects, skills, clear, date");
        break;
      case "whoami":
        out.push(
          role === "admin"
            ? "eya_hamdi (admin) -- Medical AI / Healthcare Software Engineer"
            : "visitor -- read-only access"
        );
        break;
      case "ls":
        out.push("Medical_AI_Models/  Research_Papers/  resume.txt  contact.txt");
        break;
      case "cat resume.txt":
        out.push("Eya Hamdi -- Healthcare AI Engineer");
        out.push("Focus: diagnostic ML, clinical NLP, deployed medical imaging models.");
        break;
      case "projects":
        out.push(cases.map((c) => `${c.id}: ${c.name}`).join("\n"));
        break;
      case "skills":
        out.push("PyTorch, TensorFlow, Python, Clinical NLP, DICOM, FHIR, MLOps");
        break;
      case "date":
        out.push(new Date().toString());
        break;
      case "clear":
        setLines([]);
        setInput("");
        return;
      case "":
        break;
      default:
        out.push(`'${cmd}' is not recognized as an internal or external command.`);
    }
    setLines((prev) => [...prev, ...out, ""]);
    setInput("");
  };

  return (
    <div
      style={{
        background: "#000",
        color: "#c8c8c8",
        fontFamily: "'Courier New', monospace",
        fontSize: 13,
        padding: 8,
        height: "100%",
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
      }}
      onClick={(e) => e.currentTarget.querySelector("input")?.focus()}
    >
      <div style={{ flex: 1, overflowY: "auto", whiteSpace: "pre-wrap" }}>
        {lines.join("\n")}
        <div ref={bottomRef} />
      </div>
      <div style={{ display: "flex" }}>
        <span>C:\EYA_HAMDI&gt;&nbsp;</span>
        <input
          autoFocus
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && run(input)}
          style={{
            flex: 1,
            background: "transparent",
            border: "none",
            outline: "none",
            color: "#c8c8c8",
            fontFamily: "'Courier New', monospace",
            fontSize: 13,
          }}
        />
      </div>
    </div>
  );
}

