function Clock() {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 1000 * 30);
    return () => clearInterval(t);
  }, []);
  let h = now.getHours();
  const m = now.getMinutes().toString().padStart(2, "0");
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12 || 12;
  return <span style={{ fontSize: 11 }}>{h}:{m} {ampm}</span>;
}

export default function EyaHamdiOS() {
  const [booted, setBooted] = useState(false);
  const [windows, setWindows] = useState([]);
  const [activeId, setActiveId] = useState(null);
  const [startOpen, setStartOpen] = useState(false);
  const [userRole, setUserRole] = useState("visitor");
  const [showLogin, setShowLogin] = useState(false);
  const [cases, setCases] = useState(DEFAULT_CASES);
  const [docs, setDocs] = useState(DEFAULT_DOCS);
  const zRef = useRef(10);

  const nextZ = () => (zRef.current += 1);

  // ---- shared persistent storage (visible to every visitor of this artifact) ----
  const loadShared = async (key, fallback) => {
    try {
      if (!window.storage) return fallback;
      const res = await window.storage.get(key, true);
      return res && res.value ? JSON.parse(res.value) : fallback;
    } catch (e) {
      return fallback;
    }
  };
  const saveShared = async (key, value) => {
    try {
      if (!window.storage) return;
      await window.storage.set(key, JSON.stringify(value), true);
    } catch (e) {
      console.error("storage save failed", e);
    }
  };

  useEffect(() => {
    if (!booted) return;
    (async () => {
      const [c, dRaw] = await Promise.all([
        loadShared("cases", DEFAULT_CASES),
        loadShared("documents", DEFAULT_DOCS),
      ]);
      setCases(c);
      setDocs(normalizeDocs(dRaw));
    })();
  }, [booted]); // eslint-disable-line react-hooks/exhaustive-deps

  const addCase = (newCase) => {
    setCases((prev) => {
      const next = [...prev, newCase];
      saveShared("cases", next);
      return next;
    });
  };
  const updateCase = (id, patch) => {
    setCases((prev) => {
      const next = prev.map((c) => (c.id === id ? { ...c, ...patch } : c));
      saveShared("cases", next);
      return next;
    });
  };
  const deleteCase = (id) => {
    setCases((prev) => {
      const next = prev.filter((c) => c.id !== id);
      saveShared("cases", next);
      return next;
    });
  };
  const addFolder = (name) => {
    setDocs((prev) => {
      const next = [...prev, { id: `folder-${Date.now()}`, name, items: [] }];
      saveShared("documents", next);
      return next;
    });
  };
  const renameFolder = (folderId, name) => {
    setDocs((prev) => {
      const next = prev.map((f) => (f.id === folderId ? { ...f, name } : f));
      saveShared("documents", next);
      return next;
    });
  };
  const deleteFolder = (folderId) => {
    setDocs((prev) => {
      const next = prev.filter((f) => f.id !== folderId);
      saveShared("documents", next);
      return next;
    });
  };
  const addFileToFolder = (folderId, item) => {
    setDocs((prev) => {
      const next = prev.map((f) => (f.id === folderId ? { ...f, items: [...f.items, item] } : f));
      saveShared("documents", next);
      return next;
    });
  };
  const updateFileInFolder = (folderId, fileId, patch) => {
    setDocs((prev) => {
      const next = prev.map((f) =>
        f.id === folderId ? { ...f, items: f.items.map((it) => (it.id === fileId ? { ...it, ...patch } : it)) } : f
      );
      saveShared("documents", next);
      return next;
    });
  };
  const deleteFileFromFolder = (folderId, fileId) => {
    setDocs((prev) => {
      const next = prev.map((f) =>
        f.id === folderId ? { ...f, items: f.items.filter((it) => it.id !== fileId) } : f
      );
      saveShared("documents", next);
      return next;
    });
  };

  const openWindow = useCallback((type) => {
    setWindows((prev) => {
      const existing = prev.find((w) => w.type === type && !w.singleUse);
      if (existing) {
        setActiveId(existing.id);
        return prev.map((w) => (w.id === existing.id ? { ...w, minimized: false, z: nextZ() } : w));
      }
      const def = ICON_DEFS.find((d) => d.type === type) || { title: type, icon: "computer" };
      const id = `${type}-${Date.now()}`;
      const count = prev.length;
      const nw = {
        id, type, title: def.title, icon: def.icon,
        x: 90 + count * 26, y: 60 + count * 22, w: 560, h: 400,
        z: nextZ(), minimized: false,
      };
      setActiveId(id);
      return [...prev, nw];
    });
    setStartOpen(false);
  }, []);

  const openBrowser = useCallback((url, title) => {
    setWindows((prev) => {
      const id = `browser-${Date.now()}`;
      const count = prev.length;
      const nw = {
        id, type: "browser", title: title || "Internet Explorer", icon: "ie", url,
        x: 140 + count * 20, y: 90 + count * 18, w: 620, h: 440,
        z: nextZ(), minimized: false, singleUse: true,
      };
      setActiveId(id);
      return [...prev, nw];
    });
  }, []);

  const closeWindow = (id) => setWindows((p) => p.filter((w) => w.id !== id));
  const minimizeWindow = (id) => setWindows((p) => p.map((w) => (w.id === id ? { ...w, minimized: true } : w)));
  const focusWindow = (id) => {
    setActiveId(id);
    setWindows((p) => p.map((w) => (w.id === id ? { ...w, z: nextZ() } : w)));
  };
  const dragWindow = (id, x, y) => setWindows((p) => p.map((w) => (w.id === id ? { ...w, x, y } : w)));
  const taskbarClick = (id) => {
    const w = windows.find((x) => x.id === id);
    if (!w) return;
    if (w.minimized || activeId !== id) {
      setWindows((p) => p.map((x) => (x.id === id ? { ...x, minimized: false, z: nextZ() } : x)));
      setActiveId(id);
    } else {
      minimizeWindow(id);
    }
  };

  const renderContent = (w) => {
    switch (w.type) {
      case "mycomputer":
        return (
          <MyComputerApp
            folders={docs}
            role={userRole}
            onAddFolder={addFolder}
            onRenameFolder={renameFolder}
            onDeleteFolder={deleteFolder}
            onUploadFile={addFileToFolder}
            onUpdateFile={updateFileInFolder}
            onDeleteFile={deleteFileFromFolder}
            onLaunchBrowser={openBrowser}
          />
        );
      case "casefiles":
        return <CaseFilesApp cases={cases} role={userRole} onAdd={addCase} onUpdate={updateCase} onDelete={deleteCase} onLaunchBrowser={openBrowser} />;
      case "terminal":
        return <TerminalApp cases={cases} role={userRole} />;
      case "biovitals":
        return <BioVitalsApp />;
      case "browser":
        return <BrowserApp url={w.url} />;
      default:
        return null;
    }
  };

  if (!booted) {
    return <BootSequence onDone={(role) => { setUserRole(role); setBooted(true); }} />;
  }

  return (
    <div
      style={{
        width: "100vw",
        height: "100vh",
        backgroundImage: `url(${BLISS_BG})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        position: "relative",
        overflow: "hidden",
        fontFamily: XP_FONT,
        userSelect: "none",
      }}
      onMouseDown={() => setStartOpen(false)}
    >
      {/* Desktop icons */}
      <div style={{ position: "absolute", top: 14, left: 10, display: "flex", flexDirection: "column", gap: 18 }}>
        {ICON_DEFS.map((d) => (
          <div
            key={d.type}
            onDoubleClick={() => openWindow(d.type)}
            style={{ width: 80, textAlign: "center", cursor: "pointer", padding: 4 }}
          >
            <div style={{ display: "flex", justifyContent: "center" }}>
              <PixelIcon kind={d.icon} size={40} />
            </div>
            <div style={{ color: "#fff", fontSize: 11, textShadow: "1px 1px 2px #000", marginTop: 2 }}>{d.title}</div>
          </div>
        ))}
      </div>

      {/* Windows */}
      {windows.map((w) => (
        <WindowFrame
          key={w.id}
          win={w}
          isActive={activeId === w.id}
          onFocus={focusWindow}
          onClose={closeWindow}
          onMinimize={minimizeWindow}
          onDrag={dragWindow}
        >
          {renderContent(w)}
        </WindowFrame>
      ))}

      {/* Start menu */}
      {startOpen && (
        <div
          onMouseDown={(e) => e.stopPropagation()}
          style={{
            position: "absolute", left: 0, bottom: 32, width: 230,
            background: "#ece9d8", ...bevelRaised, border: "2px solid #0a246a", zIndex: 999,
          }}
        >
          <div style={{ background: "linear-gradient(180deg,#0A246A,#3169C6)", color: "#fff", padding: "8px 10px", fontSize: 13 }}>
            <div style={{ fontWeight: "bold" }}>Eya Hamdi</div>
            <div style={{ fontSize: 10, color: "#cfe0ff" }}>
              Logged in as: {userRole === "admin" ? "Admin" : "Visitor"}
            </div>
          </div>
          {ICON_DEFS.map((d) => (
            <div
              key={d.type}
              onClick={() => openWindow(d.type)}
              style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 10px", fontSize: 12, cursor: "pointer" }}
              onMouseEnter={(e) => (e.currentTarget.style.background = "#2a5fd6")}
              onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
            >
              <PixelIcon kind={d.icon} size={20} /> {d.title}
            </div>
          ))}
          <div style={{ borderTop: "1px solid #b8b8b8", margin: "2px 0" }} />
          <div
            onClick={() => { window.__clearAdminToken?.(); setShowLogin(true); setStartOpen(false); }}
            style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 10px", fontSize: 12, cursor: "pointer" }}
            onMouseEnter={(e) => (e.currentTarget.style.background = "#2a5fd6")}
            onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
          >
            Log Off {userRole === "admin" ? "Admin" : "Visitor"}...
          </div>
        </div>
      )}

      {/* Log-off overlay: switch between Visitor / Admin without a full reboot */}
      {showLogin && (
        <div style={{ position: "absolute", inset: 0, zIndex: 5000 }}>
          <LoginScreen onLogin={(role) => { setUserRole(role); setShowLogin(false); }} />
        </div>
      )}

      {/* Taskbar */}
      <div
        style={{
          position: "absolute", left: 0, right: 0, bottom: 0, height: 32,
          background: "#245ED1", display: "flex", alignItems: "center",
          borderTop: "1px solid #6f97e8", zIndex: 1000,
        }}
      >
        <button
          onMouseDown={(e) => { e.stopPropagation(); setStartOpen((s) => !s); }}
          style={{
            height: 26, margin: "0 4px", padding: "0 14px",
            background: "#388E3C", color: "#fff", fontWeight: "bold", fontStyle: "italic",
            fontSize: 13, ...bevelRaised, border: "1px solid #1f5c22", cursor: "pointer",
          }}
        >
          start
        </button>
        <div style={{ flex: 1, display: "flex", gap: 4, padding: "0 4px", overflowX: "auto" }}>
          {windows.map((w) => (
            <button
              key={w.id}
              onClick={() => taskbarClick(w.id)}
              style={{
                display: "flex", alignItems: "center", gap: 5, height: 24, padding: "0 8px",
                background: activeId === w.id && !w.minimized ? "#1c3f8f" : "#3a6fe0",
                color: "#fff", fontSize: 11, ...bevelSunken, border: "1px solid #14337a",
                cursor: "pointer", maxWidth: 160, overflow: "hidden", whiteSpace: "nowrap", textOverflow: "ellipsis",
              }}
            >
              <PixelIcon kind={w.icon} size={14} /> {w.title}
            </button>
          ))}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#123a9c", height: "100%", padding: "0 10px" }}>
          <EcgPulse />
          <div style={{ color: "#fff" }}><Clock /></div>
        </div>
      </div>
    </div>
  );
}
